<?php
namespace App\Services;
use App\Models\Employee; use App\Models\RosterAssignment; use App\Models\RosterAvailability; use Carbon\Carbon; use Illuminate\Support\Collection;
class RosterOptimizationService {
 public function suggest(int $unitId,string $date,string $start,string $end,?int $positionId=null,?int $limit=10): Collection { $compliance=app(RosterComplianceService::class);$weekStart=Carbon::parse($date)->startOfWeek()->toDateString();$weekEnd=Carbon::parse($date)->endOfWeek()->toDateString();return Employee::where('is_active',true)->when($positionId,fn($q)=>$q->where('position_id',$positionId))->get()->map(function($e)use($unitId,$date,$start,$end,$positionId,$compliance,$weekStart,$weekEnd){$c=$compliance->evaluateEmployee($e->id,$date,$start,$end,null,$unitId,$positionId);if(!$c['allowed'])return null;$duties=RosterAssignment::where('employee_id',$e->id)->whereBetween('duty_date',[$weekStart,$weekEnd])->count();$night=RosterAssignment::where('employee_id',$e->id)->whereBetween('duty_date',[$weekStart,$weekEnd])->where('start_time','>=','18:00')->count();$a=RosterAvailability::where('employee_id',$e->id)->whereDate('available_date',$date)->first();$preference=($a&&$a->availability_type==='available')?20:0;$skill=empty($c['warnings'])?25:max(0,25-count($c['warnings'])*5);$workload=max(0,25-$duties*3-$night*2);$fairness=max(0,30-$duties*4);$score=$preference+$skill+$workload+$fairness;return ['employee'=>$e,'score'=>$score,'warnings'=>$c['warnings'],'weekly_duties'=>$duties,'night_duties'=>$night];})->filter()->sortByDesc('score')->take($limit)->values(); }
}
